// === Tab: QuadTree ===
class QuadTree {
	constructor(x, y, w, h) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.max = 10;
		this.pts = []
		this.nw = null;
		this.ne = null;
		this.se = null;
		this.sw = null;
	}

	contains(p, r = 0) {
		return (p.x + r >= this.x && p.x - r < this.x + this.w && p.y + r >= this.y && p.y - r < this.y + this.h);
	}

	insertArr(pts) {
		// console.log(pts)
		for (let p of pts) {
			this.insert(p);
		}
	}

	insert(p) {
		// out of bound?
		if (!this.contains(p)) return false;

		// store direct?
		if (this.pts.length < this.max) {
			this.pts.push(p)
			return true;
		}

		// create sub sections if not existing
		const w2 = this.w / 2;
		const h2 = this.h / 2;
		if (!this.nw) this.nw = new QuadTree(this.x, this.y, w2, h2)
		if (!this.ne) this.ne = new QuadTree(this.x + w2, this.y, w2, h2)
		if (!this.se) this.se = new QuadTree(this.x + w2, this.y + h2, w2, h2)
		if (!this.sw) this.sw = new QuadTree(this.x, this.y + h2, w2, h2)

		// try to insert the point in the sub sections
		return this.nw.insert(p) || this.ne.insert(p) || this.se.insert(p) || this.sw.insert(p);
	}

	queryAll() {
		let res = [];

		for (let p of this.pts) {
			res.push(p);
		}

		if (this.nw) res = res.concat(this.nw.queryAll());
		if (this.ne) res = res.concat(this.ne.queryAll());
		if (this.se) res = res.concat(this.se.queryAll());
		if (this.sw) res = res.concat(this.sw.queryAll());

		return res;
	}

	queryCircle(x, y, r) {
		var res = [];

		if (!this.contains({x, y}, r)) return res;


		for (let p of this.pts) {
			if (dist(p.x, p.y, x, y) <= r) res.push(p);
		}

		if (this.nw) res = res.concat(this.nw.queryCircle(x, y, r));
		if (this.ne) res = res.concat(this.ne.queryCircle(x, y, r));
		if (this.se) res = res.concat(this.se.queryCircle(x, y, r));
		if (this.sw) res = res.concat(this.sw.queryCircle(x, y, r));

		return res;
	}

	show() {
		for (let p of this.pts) {
			point(p.x, p.y)
		}
		if (this.nw) this.nw.show();
		if (this.ne) this.ne.show();
		if (this.se) this.se.show();
		if (this.sw) this.sw.show();
	}
}

// === Tab: Timer ===
class Timer {
	constructor(id, debug = false) {
		this.id = id;
		this.start = millis();
		this.last  = this.start;
		this.debug = debug;
		if (this.debug) console.log("Timer " + this.id + " started")
	}
	trigger() {
		let current = millis();
		if (this.debug) console.log("Timer " + this.id + " trigger: " + (current - this.last) + "ms")
		this.last  = current;
	}
	stop() {
		this.trigger();
		if (this.debug) console.log("Timer " + this.id + " stopt, overall: " + (this.last - this.start) + "ms")
	}
}

