let S, DST, BG;
let speech;
let font, points1, points2, points3;
let qTree, spots, ptsNumbers, maxBBox;
const FPS = 1;

function preload() {
  // Creates a p5.Font object.
  font = loadFont('https://openprocessing.org/sketch/2150899/files/RubikBurned-Regular.ttf');
}

function setup() {	
  createCanvas(S = max(windowWidth, windowHeight), S);
	pixelDensity(1);
  describe("mesh of points connected by distance forming current time");
  frameRate(FPS);

	// init speech
	speech = new p5.Speech('en-US'); // speech synthesis object "en-US"
	speech.setVolume(0.5);
	speech.setPitch(1.25);
	// speech.speak("its " + 12 + " " + 23); // say something

	BG = "navy";
	drawBackground(BG)

	noFill()
	stroke(212) // 232
	strokeWeight(1)
	strokeCap(SQUARE);

	S/=3; // char size
	DST = S/10; // distance for mesh + quadtree
	textFont(font);
	// textAlign(CENTER, CENTER);
	// textStyle(BOLD);
	textSize(S)	

	initPtsAndSpots();
	getPoints();

}

function drawBackground(bg) {
	background(bg);

	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(width/2, height/2, max(width, height)/4, width/2, height/2, max(width, height)*2);

	// Add three color stops
	gradient.addColorStop(0, "navy");
	gradient.addColorStop(1, "cyan");

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);
}

// get points for the numbers 0..9, 
// set bounding boxes for the 6 spots (hhmmss)
function initPtsAndSpots(sampleFactor = 0.15) {
	ptsNumbers = [];
	maxBBox = {x: 0, y:0, w: 0, h: 0};
	for (let i = 0; i < 10; i++) {
		const MSG = "" + i;
		const bbox = font.textBounds(MSG, 0, 0);
		const pts = font.textToPoints(MSG, 0, 0, S, { sampleFactor});
		ptsNumbers.push({bbox, pts});
		if (maxBBox.w < bbox.w) maxBBox.w = bbox.w;
		if (maxBBox.h < bbox.h) maxBBox.h = bbox.h;
	}
	// console.log(maxBBox)
	// console.log(ptsNumbers)

	spots = []
	const w = maxBBox.w;
	const h = maxBBox.h;
	const x = (width - 2 * w) / 2;
	const y = (height - 3 * h) / 2;
	spots[0] = {x: x, y: y, c: color("magenta")}
	spots[1] = {x: x + w, y: y, c: color("darkred")}
	spots[2] = {x: x, y: y + h, c: color("cyan")}
	spots[3] = {x: x + w, y: y + h, c: color("rgb(54,125,255)")}
	spots[4] = {x: x, y: y + 2 * h, c: color("orange")}
	spots[5] = {x: x + w, y: y + 2 * h, c: color("yellow")}
}

function shiftPoss(pts, delta) {
	var res = [];
	for (let p of pts) {
		res.push({x: p.x + delta.x, y: p.y + delta.y});
	}
	return res;
}

function setSpot(arr, digit, spotIdx) {
	const dx = (maxBBox.w - ptsNumbers[digit].bbox.w) / 2;
	const dy = (maxBBox.h - ptsNumbers[digit].bbox.h) / 2;
	arr.insertArr(
		shiftPoss(
			ptsNumbers[digit].pts, 
			{
				x: dx + spots[spotIdx].x - ptsNumbers[digit].bbox.x, 
				y: dy + spots[spotIdx].y - ptsNumbers[digit].bbox.y
			}
		)
	);
	// // noLoop() removed for animation
}

function getPoints(sampleFactor = 0.1) {
	if (second() === 0) speech.speak("" + hour() + " " + minute()); // say something

	qTree = new QuadTree(0, 0, width, height);

	let msg;
	msg = nf(hour(), 2);
	setSpot(qTree, msg[0], 0);
	setSpot(qTree, msg[1], 1);

	msg = nf(minute(), 2);
	setSpot(qTree, msg[0], 2);
	setSpot(qTree, msg[1], 3);

	msg = nf(second(), 2);
	setSpot(qTree, msg[0], 4);
	setSpot(qTree, msg[1], 5);
}

function draw() {
	let t = new Timer();
	if (frameCount % FPS === 0) getPoints();
	t.trigger();

	drawBackground(BG)

	drawMesh();
	t.trigger();

	if (false) {
		for (let s of spots) {
			noFill()
			stroke(s.c)
			rect(s.x, s.y, maxBBox.w, maxBBox.h)
		}
	}
	t.stop();
}


function getColorFromSpot(p, spots, bbox) {
	let clr = color("white");
	for (let s of spots) {
		if (p.x >= s.x && p.x <= s.x + bbox.w && p.y >= s.y && p.y <= s.y + bbox.h) {
			return s.c
		}
	}
	return clr;
}

function drawMesh() {
	const maxd = S/8;
	const clr1 = color("cyan")
	const clr2 = color("orange")
	push()
	for (let p of qTree.queryAll()) {
		point(p.x, p.y)
		let nearBy = qTree.queryCircle(p.x, p.y, maxd)
		for (let o of nearBy) {
			if (o!==p) {
				const d = dist(o.x, o.y, p.x, p.y);
				if (d < maxd) {
					let c1 = getColorFromSpot(p, spots, maxBBox)
					let c2 = getColorFromSpot(o, spots, maxBBox)
					var clr = lerpColor(c1, c2, 0.5);
					clr.setAlpha(255 - d/maxd*255)
					stroke(clr)
					line(o.x, o.y, p.x, p.y);
				}
			}
		}
	}
	pop();
}
